<template><div><div class="manage-page-heading"><div><span class="manage-eyebrow">{{ $ui('内容审核') }}</span><h1>{{ $ui('项目信息审核') }}</h1><p>{{ $ui('审核名称、简介、介绍及封面、画廊、视频；通过后才替换公开版本。') }}</p></div><button class="secondary-button" :disabled="loading" @click="load">{{ $ui('刷新') }}</button></div><p v-if="error" class="form-error" role="alert">{{ $ui(error) }}</p><p v-if="loading" role="status">{{ $ui('正在读取…') }}</p><p v-if="!rows.length&&!loading" class="manage-empty">{{ $ui('暂无待审核项目信息。') }}</p><article v-for="row in rows" :key="row.id" class="manage-panel"><div class="manage-section-heading"><div><h2>{{ row.payload.name }}</h2><p>{{ row.publisher_name }} · {{ new Date(row.created_at).toLocaleString($locale) }}</p></div><code>{{ row.item_id }}</code></div><h3>{{ $ui('简介') }}</h3><p class="review-copy">{{ row.payload.summary }}</p><h3>{{ $ui('详细介绍') }}</h3><p class="review-copy">{{ row.payload.description }}</p><ProjectMedia :media="row.payload.media||[]" /><form class="manage-form" @submit.prevent="decide(row,'approve')"><label>{{ $ui('审核意见') }}<textarea v-model="notes[row.id]" required maxlength="2000" rows="3" /></label><div class="actions"><button class="primary-button" :disabled="Boolean(busy)">{{ $ui('通过并公开项目信息') }}</button><button type="button" class="secondary-button" :disabled="Boolean(busy)||!notes[row.id]?.trim()" @click="decide(row,'reject')">{{ $ui('退回修改') }}</button></div></form></article><div class="manage-pagination" v-if="total>20"><button class="secondary-button" :disabled="offset===0||loading" @click="offset-=20;load()">{{ $ui('上一页') }}</button><span>{{ offset+1 }}–{{ Math.min(offset+20,total) }} / {{ total }}</span><button class="secondary-button" :disabled="offset+20>=total||loading" @click="offset+=20;load()">{{ $ui('下一页') }}</button></div></div></template>
<script setup lang="ts">
import{ref,reactive,onMounted,onBeforeUnmount}from'vue';import{store,type ProjectInfoCase}from'@/api/store';import ProjectMedia from '@/components/ProjectMedia.vue';const rows=ref<ProjectInfoCase[]>([]),total=ref(0),offset=ref(0),loading=ref(false),busy=ref(''),error=ref(''),notes=reactive<Record<string,string>>({});let active=true;
async function load(){if(loading.value)return;loading.value=true;error.value='';try{const page=await store.infoCases(offset.value);if(active){rows.value=page.data;total.value=page.pagination.total;}}catch(e){if(active)error.value=e instanceof Error?e.message:'暂时无法读取审核列表';}finally{if(active)loading.value=false;}}
async function decide(row:ProjectInfoCase,decision:'approve'|'reject'){if(busy.value)return;busy.value=row.id;error.value='';try{await store.decideInfo(row,decision,notes[row.id]);if(active)await load();}catch(e){if(active)error.value=e instanceof Error?e.message:'审核失败，请刷新后重试';}finally{if(active)busy.value='';}}
onMounted(()=>void load());onBeforeUnmount(()=>{active=false;});
</script>
<style scoped>.review-copy{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;margin:10px 0 24px}.manage-panel code{overflow-wrap:anywhere;max-width:100%;font-size:11px}.manage-section-heading{flex-wrap:wrap}</style>
